<section class="page-hero"><div class="container"><p class="section-label">Get in Touch</p><h1>Contact the Firm</h1><p class="lead">Send an enquiry and the firm can respond using the contact details you provide.</p></div></section><section class="page-section"><div class="container form-wrap"><?php if ($status === 'success'): ?><div class="notice notice--success">Thank you. Your enquiry has been received.</div><?php elseif ($status === 'invalid'): ?><div class="notice">Please check your details and try again.</div><?php endif; ?><form method="post" action="/contact" class="contact-form"><input type="hidden" name="_token" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><label>Name<input name="name" required maxlength="180"></label><label>Email<input type="email" name="email" maxlength="190"></label><label>Phone<input name="phone" maxlength="50"></label><label>Subject<input name="subject" maxlength="255"></label><label>Message<textarea name="message" required rows="7"></textarea></label><button class="button button--primary" type="submit">Send Enquiry</button></form></div></section>